      market: markets.length ? markets[i % markets.length] : "",
      side: rnd() > 0.5 ? "Long" : "Short",
      session: sessionName,
      timeMinutes,
      tag: tags[i % tags.length] || "Setup",
      rMultiple,
      duration: Math.max(3, Math.round(8 + rnd() * 420 + (i % 5) * 18)),
      mae: +(-Math.abs(rMultiple) * (0.35 + rnd() * 0.65)).toFixed(2),
      mfe: +(Math.abs(rMultiple) * (0.7 + rnd() * 1.45)).toFixed(2),
      entry: +(100 + rnd() * 900).toFixed(2),
      plannedRR: +(1.4 + rnd() * 2.2).toFixed(2),
      entryQuality: Math.round(35 + rnd() * 63),
