    "oversized":"oversized",
    "oversize":"oversized",
    "risk-overshoot":"oversized",
    "cut-winner-early":"cut-winner-early",
    "exited-early":"cut-winner-early",
    "early-exit":"cut-winner-early",
    "moved-target":"moved-target",
    "target-moved":"moved-target",
    "winner-turned-loser":"winner-to-loser",
    "let-winner-turn-to-loser":"winner-to-loser",
    "winner-to-loser":"winner-to-loser",
    "overtraded":"overtraded",
    "over-traded":"overtraded",
    "restricted-window":"restricted-window",
    "traded-restricted-window":"restricted-window",
    "revenge-trade":"revenge-trade",
