  const targetUsed = target ? metrics.totalPnl / target : 0;
  const dailyFail = dailyUsed > 1;
  const ddFail = ddUsed > 1;
  const targetHit = targetUsed >= 1;
  const minDaysPass = activeDays >= minDays;
