  const followed = stateRows.filter(row=>row.state==="followed").map(row=>row.trade);
  const broken = stateRows.filter(row=>row.state==="violated").map(row=>row.trade);
  const journaled = followed.length + broken.length;
  const stat = rows => {
    const pnl = rows.reduce((s,t)=>s+t.pnl,0);
    const r = rows.reduce((s,t)=>s+t.rMultiple,0);
    const wins = rows.filter(t=>t.pnl>0).length;
    return {
      trades:rows.length,
      pnl,
      winRate:rows.length ? wins/rows.length*100 : 0,
      avgR:rows.length ? r/rows.length : 0,
      expectancy:rows.length ? r/rows.length : 0,
    };
  };
  const violations = new Map();
  broken.forEach(t => (t.rulesViolated || ["Unspecified rule"]).forEach(rule => violations.set(rule, (violations.get(rule) || 0) + 1)));
