    pct: metrics.ruleAdherence ?? (journaled ? followed.length / journaled * 100 : metrics.disciplineScore ?? 100),
    coverage: metrics.ruleAdherenceCoverage ?? (trades.length ? journaled / trades.length * 100 : null),
    objectivePct: metrics.disciplineScore ?? null,
