  useEffect(() => {
    try { localStorage.setItem("talaria_dashboard_open_groups", JSON.stringify(dashPhaseOpenGroups)); } catch {}
  }, [dashPhaseOpenGroups]);
  useEffect(() => {
    const syncDashboardHash = () => {
      try {
        const match = String(window.location.hash || "").match(/#\/?dashboard\/([^/]+)\/([^/]+)/);
        if (match?.[2]) setDashPhaseComponent(decodeURIComponent(match[2]));
      } catch {}
    };
    syncDashboardHash();
    window.addEventListener("hashchange", syncDashboardHash);
    return () => window.removeEventListener("hashchange", syncDashboardHash);
  }, []);
  useEffect(() => {
    if (!dashSubWindow && !dashSubDragging && !dashSubResizing) return;
    const clampGeom = (g) => {
      const maxW = Math.floor(window.innerWidth * 0.9);
      const maxH = Math.floor(window.innerHeight * 0.9);
      const width = Math.max(480, Math.min(maxW, g.width));
      const height = Math.max(400, Math.min(maxH, g.height));
      return {
        width,
        height,
        left: Math.max(8, Math.min(window.innerWidth - width - 8, g.left)),
        top: Math.max(8, Math.min(window.innerHeight - height - 8, g.top)),
      };
    };
    const onMove = (e) => {
      if (dashSubDragging) {
        setDashSubGeom(g => clampGeom({...g,left:e.clientX-dashSubDragging.dx,top:e.clientY-dashSubDragging.dy}));
      }
      if (dashSubResizing) {
        setDashSubGeom(g => clampGeom({...g,width:dashSubResizing.w + (e.clientX-dashSubResizing.x),height:dashSubResizing.h + (e.clientY-dashSubResizing.y)}));
      }
    };
    const onUp = () => { setDashSubDragging(null); setDashSubResizing(null); };
    const onKey = (e) => { if (e.key === "Escape") setDashSubWindow(null); };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    window.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      window.removeEventListener("keydown", onKey);
    };
  }, [dashSubWindow, dashSubDragging, dashSubResizing]);

