    const F = (d, fr) => <svg width={s} height={s} viewBox={v} fill={cl}><path d={d} fillRule={fr}/></svg>;
    // custom icons that need special SVG structure
    // --- Layout utility icons (stroke-based for bold, clear lines at small sizes) ---
