                        rollbackOnCount:dashboardSourceFilterItems.filter(item=>(item.sessions||[]).some(session=>!!session?.rollbackAllowed)).length,
                        costsOnCount:dashboardSourceFilterItems.filter(item=>(item.sessions||[]).some(session=>librarySessionCostsOn(session))).length,
