                      {sectionBlock("Excursion", [["MFE / MAE", drawerRecord.values.mfeMae.text], ["MFE R / MAE R", drawerRecord.values.mfeMaeR.text], ["Held", drawerRecord.values.duration.text], ["Calendar", drawerRecord.values.calendar.text], ["Partials", drawerRecord.values.partials.text], ["SL Mods", drawerRecord.values.slMods.text]])}
                      {sectionBlock("Journal", [["Pre Notes", drawerRecord.values.preNotes.text], ["Post Notes", drawerRecord.values.postNotes.text], ["Pre Variables", drawerRecord.values.preVars.text], ["Post Variables", drawerRecord.values.postVars.text], ["Media", drawerRecord.values.media.text]])}
                      {sectionBlock("Provenance", [["Source", drawerRecord.sourceKind === "manual" ? "Manual" : "Auto", drawerRecord.sourceKind === "manual" ? c.gold : c.acL], ["Integrity", drawerRecord.edited ? "Edited" : "Original", drawerRecord.edited ? c.gold : c.gn], ["Created", fmtDateTime(drawerRecord.trade?.createdAt)], ["Edited", drawerRecord.edited ? fmtDateTime(drawerRecord.trade?.editedAt || drawerRecord.trade?.updatedAt) : "-"], ["Session ID", drawerRecord.values.sessionId.text]])}
