              if (totalQty > 0) return valid.reduce((sum, row) => sum + row.price * (Number.isFinite(row.qty) && row.qty > 0 ? row.qty : 0), 0) / totalQty;
              return valid.reduce((sum, row) => sum + row.price, 0) / valid.length;
