            const tradeMfeR = tradeMfeRaw == null ? null : Math.max(0, tradeMfeRaw);
            const tradeMaeR = tradeMaeRaw == null ? null : -Math.abs(tradeMaeRaw);
            const tradePostMfeR = dashFirstFiniteNumber(trade.post_mfe_r, trade.postMfeR);
