            const resolvedExcursionMode = trade.excursion_mode || trade.excursionMode || (hasSavedPostExcursion ? "extended" : hasSavedDuringExcursion ? "during" : draftBase.excursionMode);
            const avgEntryForExcursion = draftWeightedPrice(entryRowsForDraft);
