              const magnitude = Math.abs(Number(rValue));
              if (!Number.isFinite(magnitude)) return null;
              if (kind === "favorable") return sideShortForExcursion ? avgEntryForExcursion - magnitude * riskPerUnitForExcursion : avgEntryForExcursion + magnitude * riskPerUnitForExcursion;
              return sideShortForExcursion ? avgEntryForExcursion + magnitude * riskPerUnitForExcursion : avgEntryForExcursion - magnitude * riskPerUnitForExcursion;
