                        {libraryTreeHeader()}
                        {renderLibraryTreeRow({id:"compare-backtests",label:dashTxt("Backtest Sessions","جلسات الاختبار"),count:dashboardSessionPool.length,color:c.acL,depth:0,open:dashCompareTreeOpen.backtests,onClick:()=>{setDashCompareTab("backtests");toggleCompareTree("backtests");},active:dashCompareTab==="backtests"})}
