                const addTradeHasExitTiming = addTradeExitTimingEnabled && dashAddTradeHasExitTiming(dashAddTradeDraft);
                const addTradeHasExitPrice = exitRows.some(row => parseDashTradeNumber(row.price) != null && (parseDashTradeNumber(row.qty) || 0) > 0)
                  || parseDashTradeNumber(dashAddTradeDraft.exit) != null;
                const addTradeFullyExited = calculated.totalSize > 0 && calculated.exitedSize > 0 && calculated.openSize <= 0.000001;
                const addTradeHasActualExit = addTradeHasExitPrice || calculated.exitedSize > 0;
                const addTradeOutcomeReady = addTradeHasExitTiming && addTradeFullyExited && addTradeHasActualExit && currencyPreview.net != null;
                const addTradeAutoClosed = addTradeHasExitTiming && addTradeFullyExited && addTradeHasActualExit;
                const addTradeIsOpen = !addTradeAutoClosed;
                const addTradeStatusColor = value => String(value || "").toLowerCase() === "open" ? c.gold : c.acL;
                const addTradeCurrentStatusColor = addTradeStatusColor(addTradeIsOpen ? "Open" : "Closed");
                const addTradeAutoOutcome = addTradeOutcomeReady
                  ? (currencyPreview.net > 0 ? "Win" : currencyPreview.net < 0 ? "Loss" : "Breakeven")
                  : "";
                const addTradeEditorStatusColor = addTradeIsOpen ? c.gold : c.acL;
                const addTradeEditorStatusText = addTradeIsOpen ? dashTxt("Open","مفتوحة") : dashTxt("Closed","مغلقة");
