                const addTradeEditorOutcomeText = !addTradeOutcomeReady ? dashTxt("Pending","قيد الانتظار") : addTradeAutoOutcome === "Loss" ? dashTxt("Loss","خسارة") : addTradeAutoOutcome === "Breakeven" ? dashTxt("Breakeven","تعادل") : dashTxt("Win","ربح");
                const addTradePnlColor = currencyPreview.net == null ? c.tm : currencyPreview.net >= 0 ? c.gn : c.rd;
