                const addTradeDisplayedWarnings = addTradeSoftWarnings.filter(warning => !(addTradeCommissionMissing && warning === addTradeCommissionWarning));
                const addTradePreTagDefs = resolveDashAddTradeTagDefs(dashAddTradeEditorSource, "pre", dashAddTradeDraft);
