                const addTradeResolvedPostTags = normalizeDashAddTradeSingleTagState(addTradeVisiblePostTagDefs, resolveDashAddTradeAutoTagState("post", addTradeVisiblePostTagDefs, dashAddTradePostTags));
                const addTradePreSelectedCount = countDashAddTradeTagSelections(addTradePreTagDefs, addTradeResolvedPreTags);
                const addTradePostSelectedCount = countDashAddTradeTagSelections(addTradeVisiblePostTagDefs, addTradeResolvedPostTags);
