                    stopLoss:parseDashTradeNumber(dashAddTradeDraft.stopLoss),
                    planned_sl:parseDashTradeNumber(dashAddTradeDraft.stopLoss),
                    exit:calculated.avgExit,
                    exitPrice:calculated.avgExit,
