                  const activeDirectionIndex = Math.max(0, options.findIndex(option => String(dashAddTradeDraft.side || "").toLowerCase() === String(option.value).toLowerCase()));
                  const activeDirectionOption = options[activeDirectionIndex] || options[0];
                  const activeDirectionColor = activeDirectionOption.color;
                  const activeDirectionBg = activeDirectionOption.value === "Short" ? "rgba(255,80,104,0.14)" : "rgba(0,212,161,0.14)";
