                const addTradeExcursionFieldInvalid = field => !!addTradeExcursionValidation.fields?.[field];
                const addTradeExcursionError = addTradeExcursionValidation.error || "";
                const addTradeSaveValidation = dashAddTradeDraft && dashAddTradeEditorSource
