                const addTradeCanSave = !!addTradeSaveValidation.ok;
                const addTradeSaveBlockedReason = addTradeSaveValidation.error || dashTxt("Fix the highlighted fields before saving.","أصلح الحقول المحددة قبل الحفظ.");
                const formatAddTradePlainSizeValue = value => {
                  const n = Number(value || 0);
                  if (!(n > 0)) return "";
                  return Number.isInteger(n) ? String(n) : n.toFixed(2).replace(/\.?0+$/, "");
                };
                const formatAddTradeSizeValue = value => {
                  const text = formatAddTradePlainSizeValue(value);
                  if (!text) return "—";
                  return `${text}${addTradeSizeUnit ? ` ${addTradeSizeUnit}` : ""}`;
                };
                const addTradeRiskValue = currencyPreview.riskCurrency == null ? "—" : fmtMoney(currencyPreview.riskCurrency);
                const addTradeRiskSub = currencyPreview.riskCurrency == null
